/**
 * Clock rate policy.
 *
 * timeline-ms per wall-ms = uiSpeed × PLAYBACK_SPEED_REF × pace × governor
 *
 * - `PLAYBACK_SPEED_REF` makes UI 1× an easy cab/passenger pace.
 * - `pace` is the story ease: the last 10 % of a leg that ends at a photo slows
 *   to 0.6× so the Memory Pop lands; the Highlights reel multiplies plain
 *   travel by 2.8×. Intro, dwell and memory holds are never multiplied.
 * - `governor` (see buffer-governor) slows the clock when the basemap cannot
 *   keep up instead of letting the car outrun the imagery.
 */

import type { PlaybackPosition } from "./types";

export const PLAYBACK_SPEED_REF = 0.18;
export const SPEED_MIN = 0.25;
export const SPEED_MAX = 4;
export const SPEED_STEP = 0.25;
/** Presets surfaced in the Watch transport; the slider stays continuous. */
export const SPEED_PRESETS: readonly number[] = [0.5, 1, 1.5, 2, 3];
export const HIGHLIGHT_TRAVEL_MULT = 2.8;
export const APPROACH_EASE_START = 0.9;
export const APPROACH_EASE_FLOOR = 0.6;

export function clampSpeed(v: number): number {
  const n = Number(v);
  if (!Number.isFinite(n)) return 1;
  return Math.max(SPEED_MIN, Math.min(SPEED_MAX, Math.round(n * 100) / 100));
}

/** Next preset in `dir` (wraps); a value between presets moves to the neighbour in that direction. */
export function nextPreset(current: number, dir: 1 | -1): number {
  const presets = SPEED_PRESETS;
  if (dir > 0) {
    const up = presets.find((p) => p > current + 1e-9);
    return up ?? presets[0];
  }
  for (let i = presets.length - 1; i >= 0; i--) if (presets[i] < current - 1e-9) return presets[i];
  return presets[presets.length - 1];
}

export function isPreset(v: number): boolean {
  return SPEED_PRESETS.some((p) => Math.abs(p - v) < 1e-9);
}

/** Story ease for the final approach to a photo: 1 → 0.6 over the last 10 % of the leg. */
export function approachEase(frac: number, photoNext: boolean): number {
  if (!photoNext || frac <= APPROACH_EASE_START) return 1;
  const t = Math.min(1, ((frac - APPROACH_EASE_START) / (1 - APPROACH_EASE_START)) * 1.4);
  return 1 - (1 - APPROACH_EASE_FLOOR) * t;
}

export interface PaceOptions {
  highlightReel?: boolean;
}

/** Multiplier on top of the fixed clock for the current position. */
export function paceMultiplier(pos: PlaybackPosition | null | undefined, opts: PaceOptions = {}): number {
  if (!pos || pos.phase !== "travel") return 1;
  let pace = approachEase(pos.frac, pos.segment.photoNext);
  if (opts.highlightReel && pace >= 0.98) pace *= HIGHLIGHT_TRAVEL_MULT;
  return pace;
}

/** timeline-ms advanced per wall-ms. */
export function timelineRate(uiSpeed: number, pace: number, governor: number): number {
  return clampSpeed(uiSpeed) * PLAYBACK_SPEED_REF * pace * Math.max(0, governor);
}

export function formatSpeedLabel(v: number): string {
  const n = Math.round(Number(v) * 100) / 100;
  if (!Number.isFinite(n)) return "1×";
  const text = Number.isInteger(n) ? String(n) : n.toFixed(2).replace(/\.?0+$/, "");
  return `${text}×`;
}
