/**
 * The trail — the ribbon of road already driven.
 *
 * The legacy loop rebuilt the whole trail coordinate array every frame and
 * pushed it through `setData` (Mapbox re-tiles the GeoJSON on its worker,
 * which starves raster tile loads: "white map, moving arrow"). Here the trail
 * geometry is compiled once per trip and renderers advance a *cursor*:
 *
 * - `MapboxGradientTrail`: one `setData` per trip, then a per-frame
 *   `line-gradient` step at the tip's `line-progress` fraction — O(1).
 * - `ChunkedTrail` (Google 2D / Photorealistic 3D): a *settled* polyline that
 *   only grows every `settleEvery` vertices plus a bounded *head* polyline
 *   from the last settle point to the exact tip — O(settleEvery) per frame.
 */

import { clamp, haversineMeters, lerp, lowerBound, mercatorDistance } from "./math";
import type { CompiledSegment, PlaybackPosition, TrailCursor, TrailGeometry } from "./types";

// ── Geometry ─────────────────────────────────────────────────────────────────

const JOIN_EPS = 1e-7;

/**
 * Concatenate travel legs in order. Consecutive legs that share an endpoint
 * are joined on that vertex; legs that do not still connect (the car has to
 * get from one to the other) with a short join chord, exactly as movement does.
 * Sets `geometry.trailBase` on each travel leg.
 */
export function compileTrail(segments: CompiledSegment[]): TrailGeometry {
  let count = 0;
  for (const s of segments) if (s.geometry) count += s.geometry.n;
  const lngLat = new Float64Array(count * 2);
  const cum = new Float64Array(count);
  const merc = new Float64Array(count);
  let n = 0;
  let prevLat = NaN;
  let prevLng = NaN;
  let meters = 0;
  let mercDist = 0;
  for (const s of segments) {
    const g = s.geometry;
    if (!g) continue;
    let k = 0;
    if (n > 0 && Math.abs(g.coords[0] - prevLat) < JOIN_EPS && Math.abs(g.coords[1] - prevLng) < JOIN_EPS) {
      // Shared joint — this leg's vertex 0 *is* the previous last vertex.
      g.trailBase = n - 1;
      k = 1;
    } else {
      g.trailBase = n;
    }
    for (; k < g.n; k++) {
      const lat = g.coords[k * 2];
      const lng = g.coords[k * 2 + 1];
      if (n > 0) {
        meters += haversineMeters(prevLat, prevLng, lat, lng);
        mercDist += mercatorDistance(prevLat, prevLng, lat, lng);
      }
      lngLat[n * 2] = lng;
      lngLat[n * 2 + 1] = lat;
      cum[n] = meters;
      merc[n] = mercDist;
      prevLat = lat;
      prevLng = lng;
      n++;
    }
  }
  const inv = mercDist > 0 ? 1 / mercDist : 0;
  const mercFrac = new Float64Array(n);
  for (let i = 0; i < n; i++) mercFrac[i] = merc[i] * inv;
  return {
    lngLat: lngLat.subarray(0, n * 2),
    cumMeters: cum.subarray(0, n),
    mercFrac,
    totalMeters: meters,
    vertexCount: n,
  };
}

/** Exact tip on the trail for a playback position. O(1) — the position already knows its vertex. */
export function trailCursorAt(trail: TrailGeometry, pos: PlaybackPosition): TrailCursor {
  return trailCursorAtMeters(trail, pos.trailMeters, pos.trailIndex);
}

export function trailCursorAtMeters(trail: TrailGeometry, meters: number, hintIndex = -1): TrailCursor {
  const n = trail.vertexCount;
  if (n === 0) return { index: 0, meters: 0, frac: 0, mercFrac: 0, tipLng: NaN, tipLat: NaN };
  const m = clamp(meters, 0, trail.totalMeters);
  let i = hintIndex;
  if (i < 0 || i >= n || trail.cumMeters[i] > m || (i + 1 < n && trail.cumMeters[i + 1] < m)) {
    i = lowerBound(trail.cumMeters, m);
  }
  if (i >= n - 1) {
    return {
      index: n - 1,
      meters: m,
      frac: trail.totalMeters > 0 ? m / trail.totalMeters : 1,
      mercFrac: 1,
      tipLng: trail.lngLat[(n - 1) * 2],
      tipLat: trail.lngLat[(n - 1) * 2 + 1],
    };
  }
  const span = trail.cumMeters[i + 1] - trail.cumMeters[i];
  const t = span > 0 ? clamp((m - trail.cumMeters[i]) / span, 0, 1) : 0;
  return {
    index: i,
    meters: m,
    frac: trail.totalMeters > 0 ? m / trail.totalMeters : 0,
    mercFrac: lerp(trail.mercFrac[i], trail.mercFrac[i + 1], t),
    tipLng: lerp(trail.lngLat[i * 2], trail.lngLat[(i + 1) * 2], t),
    tipLat: lerp(trail.lngLat[i * 2 + 1], trail.lngLat[(i + 1) * 2 + 1], t),
  };
}

/** Full trail as `[lng, lat]` pairs (recap / export). */
export function trailCoordinates(trail: TrailGeometry, upToIndex = trail.vertexCount - 1): Array<[number, number]> {
  const out: Array<[number, number]> = [];
  const end = Math.min(trail.vertexCount - 1, upToIndex);
  for (let i = 0; i <= end; i++) out.push([trail.lngLat[i * 2], trail.lngLat[i * 2 + 1]]);
  return out;
}

// ── Renderers ────────────────────────────────────────────────────────────────

export interface TrailRenderer {
  /** Install a trip's trail. Idempotent for the same geometry object. */
  setTrail(trail: TrailGeometry, color: string): void;
  /** Paint the ribbon up to the cursor. Cheap enough to call every frame. */
  update(cursor: TrailCursor): void;
  setColor(color: string): void;
  clear(): void;
  /** Diagnostics for the perf harness. */
  readonly stats: { geometryWrites: number; headWrites: number; gradientWrites: number };
}

const TRANSPARENT = "rgba(0,0,0,0)";

/** Minimal slice of the Mapbox GL API the gradient renderer touches. */
export interface GradientMapLike {
  getSource(id: string): { setData(data: unknown): void } | undefined;
  getLayer(id: string): unknown;
  setPaintProperty(layer: string, prop: string, value: unknown): void;
}

export interface MapboxGradientTrailOptions {
  sourceId?: string;
  lineLayer?: string;
  casingLayer?: string;
  casingColor?: string;
  /** Skip gradient writes when the tip moved less than this fraction of the line. */
  minStep?: number;
}

/**
 * Mapbox: the whole trail is uploaded once (`lineMetrics: true` source); each
 * frame only rewrites `line-gradient` with a hard `step` at the tip fraction.
 */
export class MapboxGradientTrail implements TrailRenderer {
  readonly stats = { geometryWrites: 0, headWrites: 0, gradientWrites: 0 };
  private trail: TrailGeometry | null = null;
  private color = "#38bdf8";
  private lastFrac = -1;
  private readonly sourceId: string;
  private readonly lineLayer: string;
  private readonly casingLayer: string;
  private readonly casingColor: string;
  private readonly minStep: number;

  constructor(
    private map: GradientMapLike,
    opts: MapboxGradientTrailOptions = {},
  ) {
    this.sourceId = opts.sourceId ?? "active-trail";
    this.lineLayer = opts.lineLayer ?? "active-trail-line";
    this.casingLayer = opts.casingLayer ?? "active-trail-casing";
    this.casingColor = opts.casingColor ?? "#0a0e14";
    this.minStep = opts.minStep ?? 1e-6;
  }

  setTrail(trail: TrailGeometry, color: string): void {
    this.color = color;
    if (this.trail === trail) return;
    // Source not created yet (style still loading): stay unset so the next call retries.
    const src = this.map.getSource(this.sourceId);
    if (!src) return;
    this.trail = trail;
    this.lastFrac = -1;
    const coords: Array<[number, number]> = trailCoordinates(trail);
    src.setData({ type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: coords } });
    this.stats.geometryWrites += 1;
    this.writeGradient(0);
  }

  update(cursor: TrailCursor): void {
    if (!this.trail) return;
    const frac = clamp(cursor.mercFrac, 0, 1);
    if (Math.abs(frac - this.lastFrac) < this.minStep) return;
    this.writeGradient(frac);
  }

  setColor(color: string): void {
    if (color === this.color) return;
    this.color = color;
    if (this.trail && this.lastFrac >= 0) this.writeGradient(this.lastFrac);
  }

  clear(): void {
    this.trail = null;
    this.lastFrac = -1;
    const src = this.map.getSource(this.sourceId);
    if (!src) return;
    src.setData({ type: "Feature", properties: {}, geometry: { type: "LineString", coordinates: [] } });
    this.stats.geometryWrites += 1;
  }

  private writeGradient(frac: number): void {
    this.lastFrac = frac;
    const f = clamp(frac, 0, 1);
    const paint = (layer: string, color: string) => {
      if (!this.map.getLayer(layer)) return;
      const expr = f <= 0 ? TRANSPARENT : f >= 1 ? color : ["step", ["line-progress"], color, f, TRANSPARENT];
      this.map.setPaintProperty(layer, "line-gradient", expr);
    };
    paint(this.lineLayer, this.color);
    paint(this.casingLayer, this.casingColor);
    this.stats.gradientWrites += 1;
  }
}

/** Where a chunked renderer draws: two polylines, settled (rarely) and head (per frame). */
export interface TrailPartsSink {
  /** `null` settled means unchanged; an empty array removes it. */
  setTrailParts(settled: Array<[number, number]> | null, head: Array<[number, number]>, color: string): void;
  clearTrailParts(): void;
}

export interface ChunkedTrailOptions {
  /** Vertices between settled-polyline growth; default scales with the trail (256–2048). */
  settleEvery?: number;
  /** Minimum ms between head writes (Map3D geometry uploads are not free). */
  headIntervalMs?: number;
  now?: () => number;
}

/**
 * Google 2D / 3D: no gradient-along-line, so bound the per-frame upload with a
 * settled polyline that only grows every `settleEvery` vertices and a short
 * head polyline from the last settle point to the exact tip.
 */
export class ChunkedTrail implements TrailRenderer {
  readonly stats = { geometryWrites: 0, headWrites: 0, gradientWrites: 0 };
  private trail: TrailGeometry | null = null;
  private color = "#38bdf8";
  private settledCount = 0;
  private settleEvery = 256;
  private lastHeadWrite = -Infinity;
  private pendingCursor: TrailCursor | null = null;
  private readonly headIntervalMs: number;
  private readonly now: () => number;
  private readonly fixedSettle: number | undefined;

  constructor(
    private sink: TrailPartsSink,
    opts: ChunkedTrailOptions = {},
  ) {
    this.fixedSettle = opts.settleEvery;
    this.headIntervalMs = opts.headIntervalMs ?? 0;
    this.now = opts.now ?? (() => (typeof performance !== "undefined" ? performance.now() : Date.now()));
  }

  static settleEveryFor(vertexCount: number): number {
    return Math.round(clamp(vertexCount / 48, 256, 2048));
  }

  setTrail(trail: TrailGeometry, color: string): void {
    const colorChanged = color !== this.color;
    this.color = color;
    if (this.trail === trail) {
      if (colorChanged && this.pendingCursor) this.paint(this.pendingCursor, true);
      return;
    }
    this.trail = trail;
    this.settledCount = 0;
    this.settleEvery = this.fixedSettle ?? ChunkedTrail.settleEveryFor(trail.vertexCount);
    this.lastHeadWrite = -Infinity;
    this.pendingCursor = null;
    this.sink.clearTrailParts();
  }

  update(cursor: TrailCursor): void {
    if (!this.trail) return;
    this.paint(cursor, false);
  }

  setColor(color: string): void {
    if (color === this.color) return;
    this.color = color;
    if (this.trail && this.pendingCursor) this.paint(this.pendingCursor, true);
  }

  clear(): void {
    this.trail = null;
    this.settledCount = 0;
    this.pendingCursor = null;
    this.sink.clearTrailParts();
  }

  /** Vertices `[from, to]` inclusive as `[lng, lat]`. */
  private slice(from: number, to: number): Array<[number, number]> {
    const t = this.trail!;
    const out: Array<[number, number]> = [];
    for (let i = from; i <= to; i++) out.push([t.lngLat[i * 2], t.lngLat[i * 2 + 1]]);
    return out;
  }

  private paint(cursor: TrailCursor, force: boolean): void {
    const trail = this.trail!;
    this.pendingCursor = cursor;
    if (trail.vertexCount < 2 || cursor.meters <= 0) {
      if (this.settledCount !== 0 || force) {
        this.settledCount = 0;
        this.sink.clearTrailParts();
      }
      return;
    }
    const now = this.now();
    // Settled polyline covers vertices [0, settledCount). Grows in `settleEvery` steps,
    // shrinks on a backwards seek. Never includes the vertex the head starts from twice.
    const wantSettled = Math.floor(cursor.index / this.settleEvery) * this.settleEvery;
    let settled: Array<[number, number]> | null = null;
    if (wantSettled !== this.settledCount || force) {
      this.settledCount = wantSettled;
      settled = wantSettled >= 2 ? this.slice(0, wantSettled - 1) : [];
      this.stats.geometryWrites += 1;
    } else if (now - this.lastHeadWrite < this.headIntervalMs) {
      return;
    }
    const headStart = Math.max(0, this.settledCount - 1);
    const head = this.slice(headStart, cursor.index);
    const lastLng = head.length ? head[head.length - 1][0] : NaN;
    const lastLat = head.length ? head[head.length - 1][1] : NaN;
    if (Number.isFinite(cursor.tipLng) && (Math.abs(cursor.tipLng - lastLng) > 1e-9 || Math.abs(cursor.tipLat - lastLat) > 1e-9)) {
      head.push([cursor.tipLng, cursor.tipLat]);
    }
    this.lastHeadWrite = now;
    this.stats.headWrites += 1;
    this.sink.setTrailParts(settled, head, this.color);
  }
}

/** Test/diagnostic renderer that records what it was asked to draw. */
export class RecordingTrail implements TrailRenderer {
  readonly stats = { geometryWrites: 0, headWrites: 0, gradientWrites: 0 };
  trail: TrailGeometry | null = null;
  color = "";
  cursors: TrailCursor[] = [];
  setTrail(trail: TrailGeometry, color: string): void {
    this.trail = trail;
    this.color = color;
    this.stats.geometryWrites += 1;
  }
  update(cursor: TrailCursor): void {
    this.cursors.push(cursor);
    this.stats.headWrites += 1;
  }
  setColor(color: string): void {
    this.color = color;
  }
  clear(): void {
    this.trail = null;
    this.cursors = [];
  }
}
